"use client";

import { useTheme } from "next-themes";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Checkbox } from "@/components/ui/checkbox";
import { Sun01Icon, Moon01Icon, Notification01Icon, Tick01Icon, ArrowLeft01Icon } from "@hugeicons/core-free-icons";
import { HugeiconsIcon } from "@hugeicons/react";
import { cn } from "@/lib/utils";
import { useState } from "react";

interface PreferencesStepProps {
  onComplete: (data: any) => void;
  onBack: () => void;
  defaultValues: any;
}

export const PreferencesStep = ({ onComplete, onBack, defaultValues }: PreferencesStepProps) => {
  const { theme, setTheme } = useTheme();
  const [notifications, setNotifications] = useState(defaultValues.notifications ?? true);
  const [marketing, setMarketing] = useState(defaultValues.marketing ?? false);

  const handleSubmit = () => {
    onComplete({
      theme,
      notifications,
      marketing,
    });
  };

  return (
    <div className="space-y-8">
      <div className="space-y-4">
        <Label className="text-sm font-medium">Choose your appearance</Label>
        <div className="grid grid-cols-2 gap-4">
          <button
            type="button"
            onClick={() => setTheme("light")}
            className={cn(
              "flex flex-col items-center gap-3 rounded-xl border-2 p-4 transition-all hover:border-primary/50",
              theme === "light" ? "border-primary bg-primary/5" : "border-border bg-muted/30"
            )}
          >
            <HugeiconsIcon icon={Sun01Icon} className={cn("size-6", theme === "light" ? "text-primary" : "text-muted-foreground")} />
            <span className={cn("text-xs font-medium", theme === "light" ? "text-primary" : "text-muted-foreground")}>Light Mode</span>
            {theme === "light" && <HugeiconsIcon icon={Tick01Icon} className="absolute top-2 right-2 size-4 text-primary" />}
          </button>

          <button
            type="button"
            onClick={() => setTheme("dark")}
            className={cn(
              "flex flex-col items-center gap-3 rounded-xl border-2 p-4 transition-all hover:border-primary/50",
              theme === "dark" ? "border-primary bg-primary/5" : "border-border bg-muted/30"
            )}
          >
            <HugeiconsIcon icon={Moon01Icon} className={cn("size-6", theme === "dark" ? "text-primary" : "text-muted-foreground")} />
            <span className={cn("text-xs font-medium", theme === "dark" ? "text-primary" : "text-muted-foreground")}>Dark Mode</span>
            {theme === "dark" && <HugeiconsIcon icon={Tick01Icon} className="absolute top-2 right-2 size-4 text-primary" />}
          </button>
        </div>
      </div>

      <div className="space-y-4">
        <Label className="text-sm font-medium">Notifications & Updates</Label>
        <div className="space-y-3">
          <div className="flex items-start gap-4 rounded-xl border border-border p-4 bg-muted/10 transition-colors hover:bg-muted/20">
             <div className="mt-0.5 rounded-full bg-primary/10 p-2 text-primary">
                <HugeiconsIcon icon={Notification01Icon} size={18} />
             </div>
             <div className="flex-1 space-y-1">
                <div className="flex items-center justify-between">
                   <p className="text-sm font-medium leading-none">Enable Notifications</p>
                   <Checkbox checked={notifications} onCheckedChange={(checked) => setNotifications(!!checked)} />
                </div>
                <p className="text-xs text-muted-foreground">Receive alerts about your project activity.</p>
             </div>
          </div>

          <div className="flex items-start gap-4 rounded-xl border border-border p-4 bg-muted/10 transition-colors hover:bg-muted/20">
             <div className="mt-0.5 rounded-full bg-primary/10 p-2 text-primary">
                <HugeiconsIcon icon={Tick01Icon} size={18} />
             </div>
             <div className="flex-1 space-y-1">
                <div className="flex items-center justify-between">
                   <p className="text-sm font-medium leading-none">Marketing emails</p>
                   <Checkbox checked={marketing} onCheckedChange={(checked) => setMarketing(!!checked)} />
                </div>
                <p className="text-xs text-muted-foreground">Get tips, updates and offers from our team.</p>
             </div>
          </div>
        </div>
      </div>

      <div className="flex gap-3 pt-4">
        <Button type="button" variant="outline" className="flex-1" size="lg" onClick={onBack}>
           <HugeiconsIcon icon={ArrowLeft01Icon} className="mr-2" size={18} />
           Back
        </Button>
        <Button onClick={handleSubmit} className="flex-1 shadow-[0_0_20px_-5px_rgba(var(--primary),0.4)]" size="lg">
           Finish Setup
           <HugeiconsIcon icon={Tick01Icon} className="ml-2" size={18} />
        </Button>
      </div>
    </div>
  );
};
